"""Disk space node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory
from ...node_errors import NodeError
from ...system_access import checked_path, finish


class DiskSpaceNode(Node):
    """Free space on the drive that holds a folder (runs no command)."""

    node_type: ClassVar[str] = 'disk_space_node'
    display_name: ClassVar[str] = 'Disk space'
    default_alias: ClassVar[str] = 'Disk space'
    description: ClassVar[str] = 'Free space on the drive that holds a folder (runs no command)'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Inputs'
    tags: ClassVar[List[str]] = ['System']
    icon_name: ClassVar[str] = 'hard-drive'
    color_hint: ClassVar[str] = 'green'
    group: ClassVar[Optional[str]] = 'System'
    selector_section: ClassVar[Optional[str]] = 'System'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Disk space', 'description': 'The value chosen in Report, in the chosen unit', 'data_type': 'number', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}}
    default_config: ClassVar[Dict[str, Any]] = {'folder': '~', 'report': 'Free space', 'unit': 'GB', 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'folder': {'type': 'string', 'label': 'Folder', 'required': True, 'description': 'Must be inside an allowed folder (Options: system_node_folders)', 'tab': 'Parameters'}, 'report': {'type': 'select', 'label': 'Report', 'options': ['Free space', 'Used percent', 'Total size'], 'tab': 'Parameters'}, 'unit': {'type': 'select', 'label': 'Unit', 'options': ['GB', 'MB'], 'visible_when': {'report': ['Free space', 'Total size']}, 'tab': 'Parameters'}}
    ui_hints: ClassVar[Dict[str, Any]] = {'standard_output': True}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'folder_missing', 'description': 'The folder does not exist.', 'retryable': False}, {'code': 'not_allowed', 'description': 'The folder is outside the folders allowed in Options.', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        import shutil

        try:
            folder = checked_path(self.config.get("folder"), context.get_setting)
        except NodeError as exc:
            context.signal_error(exc)
            return
        usage = shutil.disk_usage(folder)
        report = str(self.config.get("report") or "Free space")
        if report == "Used percent":
            value = round(usage.used / usage.total * 100, 1) if usage.total else 0.0
        else:
            size = usage.total if report == "Total size" else usage.free
            divisor = 1024 ** 2 if self.config.get("unit") == "MB" else 1024 ** 3
            value = round(size / divisor, 2)
        finish(self, context, value, "number")
